def remember(self, conversation_id, key, value):
    if key not in ALLOWED_KEYS:
        raise MemoryPolicyError(f"{key!r} belongs to the system of record, not to memory")
    expires = self.clock() + self.ttl_seconds
    with self.db.connection() as conn:
        conn.execute(
            "INSERT INTO memory (conversation_id, key, value, expires_at) VALUES (?,?,?,?) "
            "ON CONFLICT(conversation_id, key) DO UPDATE SET value = excluded.value, expires_at = excluded.expires_at",
            (conversation_id, key, value, expires),
        )

def recall(self, conversation_id):
    now = self.clock()
    with self.db.connection() as conn:
        rows = conn.execute("SELECT key, value FROM memory WHERE conversation_id = ? AND expires_at > ?", (conversation_id, now))
        return {r["key"]: r["value"] for r in rows}
